INSERT INTO "public"."journey_items" ("id", "created_at", "title", "company", "period", "description", "type", "display_order") VALUES ('0e86885d-a897-4c6f-8016-8a3d523a466b', '2026-01-20 22:58:00.45945+00', 'Estagiário', 'COTEMIG', 'Mai de 2017 – Dez de 2017', 'Atuei como monitor e suporte técnico, auxiliando alunos com dúvidas em diversas linguagens de programação (HTML, JavaScript/jQuery, MySQL, C#, ASP.Net e PHP), redes e arquitetura, contribuindo para o aprendizado e desenvolvimento técnico.', 'experience', '5'), ('2390a1f9-5b1a-4643-b109-006614f3ba18', '2026-01-20 22:58:00.45945+00', 'Oficial do Exército Brasileiro (1º Tenente e Subcomandante)', 'Exército Brasileiro', 'Set de 2023 – Atual (7 anos de experiência militar)', 'Líder com 7 anos de experiência em comando, gestão estratégica, logística, operações e governança. Atuo como Subcomandante, principal líder e assessor direto do Comandante, responsável pela liderança institucional, gestão operacional e de pessoas, e assessoramento estratégico para tomada de decisão em ambientes de alta pressão. Experiência em gestão de riscos, licitações e contratos, e planejamento de missões de apoio à sociedade.', 'experience', '0'), ('33bceecc-27d1-439d-a27c-7e372a038deb', '2026-01-20 22:58:00.45945+00', 'Gerente de Projetos', '2C SISTEMAS', 'Fev de 2017 – Mai de 2020', 'Liderei o desenvolvimento de um sistema de gerenciamento de tarefas para a Embrapa Gado de Leite, arquitetando o sistema do zero, levantando requisitos, modelando banco de dados e desenvolvendo o backend (jQuery, MySQL, AJAX, JavaScript e PHP). Fui responsável pela gestão completa do projeto e implantação da infraestrutura.', 'experience', '2'), ('6464a78a-a4a5-40cb-9edd-8e9b2ace445f', '2026-01-20 22:58:00.45945+00', 'Técnico em Informática', 'Colégio COTEMIG', '2016 – 2017', 'Ensino médio integrado ao curso técnico, proporcionando aprofundamento em TI e experiência prática. Participei como expositor na FINIT (Feira Internacional de Negócios, Inovação e Tecnologia) em 2017.', 'education', '6'), ('9882e315-3707-4f57-9057-4fa346a47083', '2026-01-20 22:58:00.45945+00', 'Desenvolvedor Júnior', 'Brasiltrack Monitoramento Via Satélite', 'Jan de 2018 – Fev de 2019', 'Atuei na análise, desenvolvimento e manutenção de sistemas de monitoramento logístico (jQuery, MySQL, AJAX, JavaScript e PHP). Desenvolvi e mantive Gateways para comunicação com rastreadores e APIs em Python para integração entre sistemas.', 'experience', '4'), ('997a6fcd-e7e5-4ac9-8f63-dfd5335722a2', '2026-01-20 22:58:00.45945+00', 'MBA em Inteligência Artificial e Gestão de Negócios', 'Gran Faculdade', 'Nov de 2025 – Mai de 2027 (Em Conclusão)', 'Foco em aliar gestão estratégica e inovação com as mais recentes tecnologias em IA, capacitando para liderança da transformação digital e geração de valor competitivo.', 'education', '1'), ('cbdb98c4-42ee-49a3-9513-b02f08492541', '2026-01-20 22:58:00.45945+00', 'Graduação em Análise e Desenvolvimento de Sistemas', 'Estácio', 'Jan de 2022 – Abr de 2024', 'Formação sólida em desenvolvimento de software, gestão de projetos, banco de dados, programação orientada a objetos (POO) e análise de requisitos.', 'education', '3');